from ._tulis import Q, bab, kursus, latihan

# ---------------------------------------------------------------- 2 IT Support Technician
kursus(2, "IT Support Technician",
 bab(["Menyebut domain pengetahuan CompTIA A+ sebagai peta kemampuan teknisi dukungan TI.",
      "Menyebut enam langkah metodologi pemecahan masalah CompTIA.",
      "Menjelaskan prinsip 'mulai dari yang sederhana' dalam pemecahan masalah.",
      "Menjelaskan fungsi dua perintah dasar: ping dan ipconfig."],
  ("Peta kemampuan teknisi dukungan TI",
   "Artikel Infosec Institute merangkum domain ujian CompTIA A+. Core 1: Mobile Devices (13%), Networking (23%), Hardware (25%), Virtualization and Cloud Computing (11%), serta Hardware and Network Troubleshooting (28%). Core 2: Operating Systems (28%), Security (28%), Software Troubleshooting (23%), dan Operational Procedures (21%). Daftar itu bisa kamu pakai sebagai peta: teknisi dukungan TI diharapkan memahami perangkat keras, jaringan dasar, sistem operasi, keamanan dasar, dan cara bekerja yang tertib seperti dokumentasi dan komunikasi profesional. Persentase bisa berubah antar versi ujian, jadi cek situs resmi CompTIA bila kamu berencana ikut ujian."),
  ("Metodologi pemecahan masalah",
   "Blog resmi CompTIA tentang metodologi pemecahan masalah menjelaskan langkah-langkahnya: (1) identifikasi masalah, (2) susun teori penyebab yang mungkin, (3) uji teori, (4) susun rencana tindakan dan terapkan solusi, (5) verifikasi fungsi sistem secara penuh dan terapkan langkah pencegahan, dan (6) dokumentasikan temuan. Prinsip penuntunnya: keep it simple, yaitu mulai dari pemeriksaan dasar seperti apakah perangkat tersambung ke listrik, menyala, dan sudah dimulai ulang, baru bergerak ke penyebab yang lebih rumit."),
  ("Dua perintah dasar",
   "Dokumentasi Microsoft menjelaskan ping sebagai perintah yang memverifikasi konektivitas tingkat IP ke host lain dengan mengirim pesan ICMP Echo Request dan melaporkan Echo Reply beserta waktu bolak-balik. Dokumentasi itu menyebut: bila ping ke alamat IP berhasil tetapi ping ke nama host gagal, masalah kemungkinan ada pada resolusi nama. ipconfig menampilkan nilai konfigurasi TCP/IP yang sedang berlaku dan menyegarkan pengaturan DHCP dan DNS; tanpa parameter ia menampilkan alamat IPv4 dan IPv6, subnet mask, dan gateway bawaan semua adapter.")),
 bab(["Memakai ipconfig /all, /release, /renew, dan /flushdns sesuai fungsinya.",
      "Memakai opsi ping /n, /t, dan /l.",
      "Menjelaskan arti Request timed out.",
      "Menjelaskan prinsip menanyakan hal yang berubah sebelum mengubah apa pun."],
  ("Parameter ipconfig",
   "Menurut dokumentasi Microsoft: /all menampilkan konfigurasi TCP/IP lengkap semua adapter; /release mengirim pesan DHCPRELEASE ke server DHCP untuk melepas konfigurasi DHCP dan membuang konfigurasi alamat IP (dokumentasi menyebut ini menonaktifkan TCP/IP untuk adapter yang diatur mendapatkan alamat otomatis); /renew memperbarui konfigurasi DHCP; /flushdns mengosongkan cache resolver DNS klien, berguna saat pemecahan masalah DNS untuk membuang entri negatif; /displaydns menampilkan isi cache itu."),
  ("Opsi ping",
   "Dokumentasi ping: /t mengirim Echo Request terus-menerus sampai dihentikan (Ctrl+C untuk berhenti); /n menentukan jumlah Echo Request (bawaan 4); /l menentukan ukuran data dalam byte (bawaan 32, maksimal 65.500). Contoh dari dokumentasi: ping /n 10 /l 1000 10.0.99.221 mengirim 10 permintaan berukuran data 1.000 byte. Bila tidak ada balasan dalam batas waktu (bawaan 4.000 ms), ping melaporkan Request timed out. Contoh keluaran: 'Reply from 192.168.239.132: bytes=32 time=101ms TTL=124'.")),
 bab(["Menerapkan langkah identifikasi masalah: bertanya, melihat perubahan, mereproduksi.",
      "Memilih pendekatan top-to-bottom atau bottom-to-top.",
      "Menguji teori tanpa mengubah konfigurasi.",
      "Menjelaskan pentingnya rencana mundur (rollback) dan backup."],
  ("Identifikasi dan teori",
   "Menurut CompTIA: pada langkah identifikasi kumpulkan informasi dari log, pesan error, dan pengguna; catat gejala; periksa perubahan terbaru; coba mereproduksi masalah; tangani satu masalah satu waktu; dan persempit ruang lingkup. Pastikan penyebab akar ditemukan sebelum mengubah apa pun. Pada langkah teori: buat dugaan terpelajar memakai dokumentasi vendor, dokumentasi organisasi, dan pencarian online; pertanyakan hal yang jelas; pilih pendekatan top-to-bottom atau bottom-to-top untuk teknologi berlapis seperti jaringan; dan catat semuanya."),
  ("Uji, rencana, dan rollback",
   "CompTIA: pengujian teori dilakukan tanpa mengubah konfigurasi; pada jaringan periksa konfigurasi IP, perangkat seperti router dan switch, serta layanan DNS, DHCP, dan firewall; pada workstation bisa memakai perangkat keras yang diketahui baik sebagai pengganti. Jika teori salah, kembali ke langkah 1. Sebelum mengubah, susun rencana: pertimbangkan waktu henti, unduhan perangkat lunak atau driver, uji di lingkungan percobaan, dan persetujuan perubahan. Cadangkan data yang berisiko, dan siapkan rencana mundur agar perubahan dapat dibalik.")),
 bab(["Menjelaskan langkah verifikasi dan dokumentasi pada tiket dukungan.",
      "Mengenali tanda phishing menurut CISA dan tindakan pengguna.",
      "Menjelaskan tiga tujuan keamanan (CIA) pada tingkat dasar.",
      "Menjelaskan MFA secara sederhana."],
  ("Verifikasi dan dokumentasi",
   "CompTIA: setelah solusi diterapkan, pastikan sistem berfungsi penuh, sebaiknya dengan bantuan pengguna yang memakainya, dan terapkan perbaikan yang sama pada server atau perangkat lain yang terdampak. Lalu dokumentasikan langkah, perubahan, teori, dan hasil riset. Dokumentasi membantu menghadapi masalah serupa, memberi tahu apa yang sudah dicoba, dan memudahkan membalik perubahan yang menimbulkan efek tak terduga. Domain Core 2 'Operational Procedures' juga memuat komunikasi profesional dan dokumentasi."),
  ("Keamanan dasar untuk pengguna",
   "Panduan CISA tentang phishing menyebut tanda: bahasa mendesak atau emosional, permintaan data pribadi atau keuangan, tautan pendek tidak tepercaya, serta alamat atau tautan yang keliru. Tindakan: jangan klik tautan atau lampiran yang mencurigakan, laporkan, dan hapus tanpa membalas. CISA menjelaskan MFA sebagai verifikasi identitas dengan dua atau lebih autentikator sehingga kata sandi curian saja tidak cukup. Definisi NIST menyebut keamanan informasi melindungi kerahasiaan, integritas, dan ketersediaan.")),
 bab(["Menerapkan metodologi pada skenario pengguna tidak bisa membuka situs.",
      "Menerapkan metodologi pada skenario komputer tidak mendapat alamat IP.",
      "Menulis catatan tiket yang jelas.",
      "Menjelaskan kapan mengeskalasi."],
  ("Skenario: tidak bisa membuka situs",
   "Pengguna melapor tidak bisa membuka situs. Identifikasi: tanyakan sejak kapan, apakah semua situs atau satu situs, dan apa yang berubah. Teori: masalah DNS atau jaringan. Uji: jalankan ping ke alamat IP lalu ke nama; menurut dokumentasi Microsoft, bila ping IP berhasil tetapi nama gagal, masalah kemungkinan resolusi nama. Tindakan: ipconfig /flushdns lalu uji ulang. Verifikasi bersama pengguna. Dokumentasi: catat gejala, uji, tindakan, dan hasil."),
  ("Skenario: komputer tidak mendapat alamat IP",
   "Komputer baru dipasang tidak mendapat alamat. Identifikasi: periksa kabel dan lampu, sesuai prinsip keep it simple. Uji: ipconfig /all untuk melihat konfigurasi saat ini; setelah memastikan kabel tersambung, coba ipconfig /renew. Dokumentasi Microsoft menyebut /renew hanya tersedia pada adapter yang diatur mendapat alamat otomatis. Bila tetap gagal, periksa layanan DHCP di jaringan dan eskalasikan dengan catatan lengkap tentang apa yang sudah dicoba.")),
 {"title": "Buku panduan dukungan TI untuk sekolah",
  "brief": "Buat buku panduan (dokumen) berisi 10 skenario dukungan TI yang sering terjadi di sekolah (misalnya tidak ada internet, tidak bisa login, printer tidak terdeteksi). Untuk tiap skenario tulis langkah sesuai enam langkah metodologi CompTIA, perintah yang dipakai (misalnya ping dan ipconfig), dan contoh catatan tiket. Uji minimal 3 skenario di komputer lab atau mesin virtual milikmu sendiri.",
  "criteria": ["Sepuluh skenario dengan gejala dan pertanyaan identifikasi.",
               "Setiap skenario memuat teori penyebab dan cara menguji tanpa mengubah konfigurasi.",
               "Penggunaan ping dan ipconfig dijelaskan benar sesuai dokumentasi Microsoft.",
               "Rencana tindakan dengan rencana mundur dan backup bila perlu.",
               "Contoh catatan tiket lengkap (gejala, uji, tindakan, hasil, verifikasi).",
               "Bukti pengujian minimal tiga skenario di lingkungan milikmu sendiri.",
               "Daftar sumber (CompTIA, Microsoft, CISA) dan batas pengetahuanmu."]},
 [
 Q(2, "A", "Langkah pertama metodologi pemecahan masalah CompTIA adalah:", "Identifikasi masalah", "Dokumentasi", "Mengganti perangkat", "Menginstal ulang", "a", "Urutan: identifikasi, teori, uji, rencana dan solusi, verifikasi, dokumentasi."),
 Q(2, "K", "Berapa langkah metodologi pemecahan masalah CompTIA?", "Tiga", "Enam", "Sepuluh", "Dua", "b", "Enam langkah dari identifikasi sampai dokumentasi."),
 Q(2, "K", "Prinsip 'keep it simple' berarti:", "Mulai dari pemeriksaan dasar seperti perangkat tersambung listrik, menyala, dan dimulai ulang", "Langsung menginstal ulang sistem operasi supaya semua kemungkinan penyebab hilang sekaligus", "Mengganti semua kabel dan perangkat keras sebelum bertanya kepada pengguna", "Mengabaikan laporan pengguna sampai masalahnya terulang beberapa kali", "a", "CompTIA: mulai dari pemeriksaan dasar sebelum penyebab yang rumit."),
 Q(2, "K", "Ping bekerja dengan mengirim:", "ICMP Echo Request", "Email", "File besar", "Paket DHCP", "a", "Dokumentasi Microsoft: ping mengirim ICMP Echo Request dan melaporkan Echo Reply."),
 Q(2, "K", "Domain Core 1 CompTIA A+ dengan persentase terbesar menurut artikel Infosec Institute:", "Hardware and Network Troubleshooting (28%)", "Virtualization and Cloud Computing (11%)", "Mobile Devices and Accessories (13%)", "Networking and Protocols (23%)", "a", "Pemecahan masalah perangkat keras dan jaringan 28%."),
 Q(2, "K", "ipconfig tanpa parameter menampilkan:", "Alamat IP, subnet mask, dan gateway bawaan adapter", "Isi hard disk beserta ruang kosong pada setiap partisi komputer", "Daftar program yang terpasang beserta versi dan tanggal pemasangannya", "Suhu CPU dan kecepatan kipas pada saat perintah dijalankan", "a", "Menurut dokumentasi Microsoft, itu keluaran bawaan ipconfig."),
 Q(2, "A", "Bila ping ke alamat IP berhasil tetapi ke nama host gagal, kemungkinan masalah ada pada:", "Resolusi nama", "Kabel putus", "Listrik", "Monitor", "a", "Dokumentasi Microsoft menyebut kemungkinan masalah resolusi nama."),
 Q(3, "K", "ipconfig /flushdns fungsinya:", "Mengosongkan cache resolver DNS klien", "Melepas alamat IP", "Menampilkan semua adapter", "Memperbarui DHCP", "a", "Dokumentasi: flush dan reset isi cache resolver DNS klien."),
 Q(3, "K", "ipconfig /renew fungsinya:", "Memperbarui konfigurasi DHCP", "Mengosongkan DNS", "Menghapus adapter", "Mematikan Wi-Fi", "a", "Dokumentasi: renew memperbarui konfigurasi DHCP."),
 Q(3, "K", "ipconfig /release:", "Melepas konfigurasi DHCP dan membuang konfigurasi alamat IP", "Menampilkan isi cache resolver DNS yang tersimpan di komputer klien", "Menambahkan alamat IP statis baru pada adapter jaringan yang dipilih", "Mengubah gateway bawaan menjadi alamat yang diminta teknisi jaringan", "a", "Dokumentasi: mengirim DHCPRELEASE dan membuang konfigurasi alamat IP."),
 Q(3, "K", "Jumlah Echo Request bawaan pada ping Windows menurut dokumentasi:", "4", "10", "32", "1", "a", "/n menentukan jumlah; bawaan 4."),
 Q(3, "K", "Ukuran data bawaan Echo Request ping menurut dokumentasi:", "32 byte", "64 byte", "1.000 byte", "65.500 byte", "a", "Bawaan 32 byte; maksimum 65.500."),
 Q(3, "A", "Opsi ping untuk mengirim terus-menerus sampai dihentikan:", "/t", "/n", "/l", "/w", "a", "/t mengirim sampai dihentikan; Ctrl+C untuk berhenti."),
 Q(3, "K", "Pesan 'Request timed out' pada ping berarti:", "Tidak ada balasan diterima dalam batas waktu", "Ping berhasil dan balasan diterima dalam waktu sangat singkat", "Kabel jaringan sudah terpasang dengan benar pada kedua ujungnya", "Penerjemahan nama DNS selesai tanpa kesalahan sedikit pun", "a", "Bawaan batas waktu 4.000 ms."),
 Q(4, "K", "Pada langkah identifikasi masalah, CompTIA menyarankan antara lain:", "Memeriksa perubahan terbaru dan mencoba mereproduksi masalah", "Langsung mengubah konfigurasi sebelum gejalanya dipahami dengan jelas", "Mengabaikan penjelasan pengguna karena dianggap kurang teknis", "Mengganti perangkat yang paling mahal supaya masalah cepat hilang", "a", "Juga menangani satu masalah satu waktu dan mempersempit ruang lingkup."),
 Q(4, "K", "Menguji teori sebaiknya dilakukan:", "Tanpa membuat perubahan konfigurasi", "Dengan mengubah sebanyak mungkin", "Dengan menghapus data", "Tanpa catatan", "a", "CompTIA: konfirmasi penyebab tanpa mengubah konfigurasi."),
 Q(4, "K", "Bila teori yang diuji ternyata salah, langkah berikutnya:", "Kembali ke langkah identifikasi", "Menutup tiket", "Mengabaikan", "Menyalahkan pengguna", "a", "CompTIA: jika teori salah, kembali ke langkah 1."),
 Q(4, "K", "Sebelum menerapkan perbaikan yang berisiko, CompTIA menyarankan:", "Mencadangkan data dan menyiapkan rencana mundur", "Langsung menerapkan perbaikan tanpa rencana untuk membatalkannya", "Menghapus log supaya jejak perubahan lama tidak membingungkan", "Mematikan semua perangkat lain di jaringan selama perbaikan", "a", "Back up data yang berisiko dan sediakan rollback plan."),
 Q(4, "A", "Pendekatan 'bottom-to-top' pada jaringan berarti:", "Memeriksa dari lapisan bawah (fisik) ke atas", "Memeriksa dari aplikasi pengguna saja tanpa menyentuh kabel", "Tidak memeriksa apa pun sebelum perangkat diganti baru", "Menghapus kabel lama dan memasang kabel baru di setiap ruangan", "a", "CompTIA menyebut top-to-bottom atau bottom-to-top untuk teknologi berlapis seperti jaringan."),
 Q(4, "K", "Pada pengujian teori untuk workstation, CompTIA menyebut cara:", "Memakai perangkat keras pengganti yang diketahui baik", "Membeli komputer baru lalu memindahkan seluruh data pengguna", "Mematikan seluruh jaringan sekolah selama pengujian berlangsung", "Menghapus akun pengguna lalu membuatnya kembali dari awal", "a", "Known-good hardware dapat dipakai untuk menguji teori."),
 Q(4, "K", "Tujuan verifikasi fungsi sistem sebaiknya melibatkan:", "Pengguna yang memakai sistem itu", "Penyerang yang pernah mencoba masuk ke jaringan sekolah", "Tidak ada pihak lain karena teknisi sudah yakin berhasil", "Hanya teknisi lain yang bertugas pada shift berikutnya", "a", "CompTIA: konfirmasi dengan bantuan pengguna yang mengandalkan sistem."),
 Q(5, "K", "Pengguna tidak bisa membuka situs; ping alamat IP berhasil, ping nama gagal. Langkah berikutnya yang paling masuk akal:", "ipconfig /flushdns lalu uji ulang", "Mengganti kabel", "Menginstal ulang Windows", "Mengganti monitor", "a", "Gejala mengarah ke resolusi nama; flush cache DNS adalah tindakan yang disebut dokumentasi untuk troubleshooting DNS."),
 Q(5, "K", "Komputer baru tidak mendapat alamat IP. Langkah awal paling sesuai 'keep it simple':", "Periksa kabel dan lampu link lalu ipconfig /all", "Instal ulang sistem operasi lalu pasang semua driver dari awal", "Ganti motherboard karena kartu jaringan bawaan pasti rusak", "Ganti router sekolah karena komputer lain mungkin ikut bermasalah", "a", "Mulai dari pemeriksaan dasar sebelum penyebab rumit."),
 Q(5, "K", "ipconfig /renew hanya tersedia pada:", "Adapter yang diatur mendapat alamat IP otomatis", "Semua adapter jaringan, termasuk yang memakai alamat IP statis", "Printer jaringan yang memiliki alamat IP tetap dari administrator", "Monitor yang tersambung lewat kabel HDMI ke komputer", "a", "Dokumentasi Microsoft menyebut batasan itu."),
 Q(5, "K", "Dokumentasi tiket yang baik memuat:", "Gejala, uji, tindakan, hasil, dan verifikasi", "Hanya nama teknisi yang menangani dan jam ia selesai bekerja", "Hanya kata 'beres' supaya tiket cepat ditutup dan tidak membingungkan", "Hanya tanggal tiket dibuka tanpa keterangan tentang masalahnya", "a", "CompTIA: catat langkah, perubahan, teori, dan hasil."),
 Q(5, "A", "Salah satu tanda phishing menurut CISA:", "Permintaan data pribadi atau keuangan", "Pesan berbahasa baku yang ditulis dengan tata bahasa benar", "Pesan singkat yang dikirim hanya satu kali dalam sehari", "Pesan yang memakai emoji dan gambar berwarna di dalamnya", "a", "CISA menyebut permintaan data pribadi atau keuangan sebagai tanda."),
 Q(5, "K", "MFA menurut CISA berarti:", "Verifikasi identitas dengan dua atau lebih autentikator", "Membuat kata sandi lebih panjang dan lebih rumit untuk satu akun", "Jaringan privat virtual untuk mengamankan lalu lintas internet", "Program antivirus yang memeriksa file unduhan secara berkala", "a", "Kata sandi curian saja tidak cukup."),
 Q(5, "K", "Tiga tujuan keamanan informasi menurut NIST:", "Kerahasiaan, integritas, ketersediaan", "Kecepatan, murah, ringan", "Warna, bentuk, ukuran", "Input, proses, output", "a", "Definisi glosarium NIST menyebut ketiganya sebagai tujuan keamanan informasi."),
 ],
 sumber=[("Infosec Institute: CompTIA A+ exam domains", "https://infosecinstitute.com/resources/a/comptia-a-exam-domains-overview/"),
         ("CompTIA: Troubleshooting methodology", "https://www.comptia.org/blog/troubleshooting-methodology"),
         ("Microsoft Learn: ipconfig", "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/ipconfig"),
         ("Microsoft Learn: ping", "https://learn.microsoft.com/sv-se/windows-server/administration/windows-commands/ping"),
         ("CISA: Recognize and Report Phishing", "https://www.cisa.gov/secure-our-world/recognize-and-report-phishing"),
         ("CISA: More Than a Password (MFA)", "https://www.cisa.gov/MFA"),
         ("NIST Glossary: Information Security", "https://csrc.nist.gov/glossary/term/information_security")])
latihan(2,
 ["Salin enam langkah metodologi CompTIA ke kartu belajar dan tulis satu contoh di rumahmu untuk tiap langkah.",
  "Buat peta kemampuanmu: nilai dirimu 1 sampai 5 pada tiap domain A+ dan pilih dua yang mau dikuatkan.",
  "Jalankan ping ke 127.0.0.1 dan ke gateway, lalu tulis arti setiap bagian keluarannya."],
 ["Jalankan ipconfig /all dan catat alamat IP, mask, gateway, dan server DNS komputermu.",
  "Coba ipconfig /displaydns lalu /flushdns dan catat perbedaannya.",
  "Jalankan ping /n 10 /l 1000 ke gateway lab dan catat hasilnya."],
 ["Pilih satu masalah di komputer lab dan tulis tahap identifikasi: pertanyaan, gejala, perubahan terakhir.",
  "Tulis dua teori penyebab untuk satu masalah jaringan dan cara menguji tanpa mengubah konfigurasi.",
  "Tulis rencana tindakan dan rencana mundur untuk satu perbaikan."],
 ["Tulis tiket lengkap untuk skenario 'tidak bisa membuka situs' dan minta temanmu memeriksa.",
  "Susun panduan satu halaman bagi siswa tentang mengenali email phishing berdasarkan CISA.",
  "Tulis kriteria kapan kamu mengeskalasi masalah ke teknisi lebih senior."])
